<template>
  <div class="gomoku-game">
    <h1>五子棋对战</h1>

    <!-- 错误提示 -->
    <div v-if="hasError" class="error-message">
      <p>⚠️ {{ errorMessage }}</p>
      <button class="close-btn" @click="clearError">关闭</button>
    </div>

    <!-- 游戏信息显示 -->
    <div class="game-info">
      <div class="player-info">
        <div class="player black">
          <span class="stone black"></span>
          <span>黑方：{{ internalGameData.blackPlayer?.name || "黑棋" }}</span>
          <span
v-if="internalGameData.ranks && internalGameData.ranks[0] !== undefined" 
                :class="['rank', internalGameData.ranks[0] >= 0 ? 'positive' : 'negative']">
            {{ internalGameData.ranks[0] > 0 ? "+" : "" }}{{ internalGameData.ranks[0] }}
          </span>
        </div>
        <div class="player white">
          <span class="stone white"></span>
          <span>白方：{{ internalGameData.whitePlayer?.name || "白棋" }}</span>
          <span
v-if="internalGameData.ranks && internalGameData.ranks[1] !== undefined" 
                :class="['rank', internalGameData.ranks[1] >= 0 ? 'positive' : 'negative']">
            {{ internalGameData.ranks[1] > 0 ? "+" : "" }}{{ internalGameData.ranks[1] }}
          </span>
        </div>
      </div>
      <div class="game-status">
        <p v-if="internalGameData.result">结果：{{ internalGameData.result }}</p>
        <p>当前步数：{{ currentStep }} / {{ internalGameData.moves?.length || 0 }}</p>
      </div>
    </div>

    <!-- 棋盘Canvas -->
    <div class="board-container">
      <canvas ref="boardCanvas" :width="canvasWidth" :height="canvasHeight" class="go-board"></canvas>
    </div>

    <!-- 控制按钮 -->
    <div class="controls">
      <button class="control-btn" @click="gotoStart"><span>⏮️</span> 开始</button>
      <button class="control-btn" @click="prevStep"><span>⏪</span> 上一步</button>
      <button class="control-btn primary" @click="togglePlay">
        <span v-if="isPlaying">⏸️</span>
        <span v-else>▶️</span>
        {{ isPlaying ? "暂停" : "播放" }}
      </button>
      <button class="control-btn" @click="nextStep"><span>⏩</span> 下一步</button>
      <button class="control-btn" @click="gotoEnd"><span>⏭️</span> 结束</button>
      <div class="speed-control">
        <label>播放速度：</label>
        <input v-model="playSpeed" type="range" min="0.5" max="3" step="0.5" class="speed-slider" />
        <span>{{ playSpeed }}x</span>
      </div>
    </div>

    <!-- 落子记录 -->
    <div class="move-history">
      <h3>落子记录</h3>
      <div class="moves">
        <div
v-for="(move, index) in internalGameData.moves" :key="index"
          :class="['move-item', { active: index === currentStep - 1 }]" @click="gotoStep(index + 1)">
          <span class="move-number">{{ index + 1 }}</span>
          <span class="stone" :class="move.color"></span>
          <span class="move-position">{{ formatPosition(move.x, move.y) }}</span>
          <span v-if="move.time" class="timestamp">{{ formatTime(move.time) }}</span>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, onMounted, watch, onUnmounted } from "vue";
import type { GenericGameData } from "@/types/bot";
import { useBreakpoint } from "@/composables/useBreakpoint";

// 判断是否为非空对象，供类型守卫内部收窄使用
const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null;

// 类型守卫函数
function isGenericGameData(data: unknown): data is GenericGameData {
  if (!isRecord(data)) {
    return false;
  }
  return (
    typeof data.id === "string" &&
    data.id.length > 0 &&
    typeof data.gameKey === "string" &&
    typeof data.gameTitle === "string" &&
    typeof data.status === "number" &&
    typeof data.infoData === "object" &&
    data.infoData !== null &&
    typeof data.paramData === "object" &&
    data.paramData !== null &&
    Array.isArray(data.agents)
  );
}

// 验证移动数据
function validateMove(move: unknown): move is { x: number; y: number; time?: number } {
  if (!isRecord(move)) {
    return false;
  }
  return (
    typeof move.x === "number" &&
    typeof move.y === "number" &&
    move.x >= 0 &&
    move.y >= 0 &&
    (move.time === undefined || typeof move.time === "number")
  );
}

// 验证移动数组
function validateMoves(moves: unknown[]): boolean {
  if (!Array.isArray(moves)) {
    console.error("Gomoku: moves 不是数组");
    return false;
  }

  for (let i = 0; i < moves.length; i++) {
    if (!validateMove(moves[i])) {
      console.error(`Gomoku: moves[${i}] 数据无效:`, moves[i]);
      return false;
    }
  }

  return true;
}

// 错误提示组件
const errorMessage = ref<string>("");
const hasError = ref(false);

function showError(message: string): void {
  errorMessage.value = message;
  hasError.value = true;
  console.error("Gomoku Error:", message);
}

function clearError(): void {
  errorMessage.value = "";
  hasError.value = false;
}

// 定义五子棋特定的数据结构
interface Player {
  id: string;
  name: string;
  type?: string;
}

interface Move {
  x: number;
  y: number;
  color: "black" | "white";
  time?: number;
}

interface GameData {
  id: string;
  boardSize: number;
  startTime?: number;
  endTime?: number;
  blackPlayer: Player;
  whitePlayer: Player;
  moves: Move[];
  result?: string;
  winner?: "black" | "white" | "draw";
  // evaluateBoard 未连成五子时返回 null，故这里允许 null
  winningLine?: { x1: number; y1: number; x2: number; y2: number }[] | null;
  ranks?: number[];
}

// Props - 接收通用游戏数据
const props = defineProps<{
  gameData: GenericGameData;
}>();

// Emits
defineEmits<{
  (e: "update:gameData", value: GenericGameData): void;
}>();

// 五子棋游戏的内部数据
const internalGameData = ref<GameData>({
  id: "demo-game-1",
  boardSize: 15,
  startTime: Date.now() - 3600000,
  blackPlayer: {
    id: "player1",
    name: "黑方选手",
    type: "bot",
  },
  whitePlayer: {
    id: "player2",
    name: "白方选手",
    type: "bot",
  },
  moves: [],
  result: "游戏进行中",
});

// 组件状态
const boardCanvas = ref<HTMLCanvasElement>();
const canvasWidth = ref(600);
const canvasHeight = ref(600);
const { isMobile } = useBreakpoint();
const currentStep = ref(0);
const isPlaying = ref(false);
const playSpeed = ref(1);
let animationFrameId: number | null = null;
let lastPlayTime = 0;
let lastBlinkTime = 0;
const blinkIntensity = ref(1);

// 动画相关状态
const dropAnimationProgress = ref(0);
const lineAnimationProgress = ref(0);
const isDropAnimating = ref(false);
const isLineAnimating = ref(false);
let animationStartTime = 0;
const DROP_ANIMATION_DURATION = 300;
const LINE_ANIMATION_DURATION = 800;

// 缓存上一次的 moves 数据，避免不必要的更新
let lastMovesHash = "";

// 将通用游戏数据转换为五子棋特定数据
function convertGenericToGomokuData(genericData: GenericGameData): GameData {
  clearError();

  // 验证输入数据
  if (!isGenericGameData(genericData)) {
    showError("无效的游戏数据格式");
    return internalGameData.value;
  }

  console.log("Gomoku: 开始转换数据", genericData);

  const result: GameData = {
    id: genericData.id,
    boardSize: 15,
    startTime: Date.now(),
    blackPlayer: {
      id: "black",
      name: "黑方选手",
      type: "bot",
    },
    whitePlayer: {
      id: "white",
      name: "白方选手",
      type: "bot",
    },
    moves: [],
    result: "游戏进行中",
  };

  // 从 infoData 中提取玩家信息
  if (genericData.infoData) {
    const info = genericData.infoData;
    console.log("Gomoku: infoData =", info);
    console.log("Gomoku: agents =", genericData.agents);

    const blackInfo = info.black;
    if (isRecord(blackInfo) && genericData.agents) {
      const blackAgent = genericData.agents.find((agent) => agent.id === blackInfo.id);
      console.log("Gomoku: blackAgent =", blackAgent, "info.black =", blackInfo.id);
      if (blackAgent) {
        result.blackPlayer = {
          id: blackAgent.id.toString(),
          name: blackAgent.name,
          type: "bot",
        };
      }
    }
    const whiteInfo = info.white;
    if (isRecord(whiteInfo) && genericData.agents) {
      const whiteAgent = genericData.agents.find((agent) => agent.id === whiteInfo.id);
      console.log("Gomoku: whiteAgent =", whiteAgent, "info.white =", whiteInfo.id);
      if (whiteAgent) {
        result.whitePlayer = {
          id: whiteAgent.id.toString(),
          name: whiteAgent.name,
          type: "bot",
        };
      }
    }
  }

  console.log("Gomoku: 转换后的玩家信息", {
    blackPlayer: result.blackPlayer,
    whitePlayer: result.whitePlayer,
  });

  // 传递 ranks 数据
  if (genericData.ranks) {
    result.ranks = genericData.ranks;
  }

  // 从 paramData 中提取落子记录
  const paramMoves = genericData.paramData.moves;
  if (paramMoves) {
    // 非数组或校验失败都视为数据无效（validateMoves 需要 unknown[]，故先做数组收窄）
    if (!Array.isArray(paramMoves) || !validateMoves(paramMoves)) {
      showError("落子数据格式无效");
      return result;
    }

    result.moves = paramMoves.filter(validateMove).map((move, index): Move => ({
      x: move.x,
      y: move.y,
      color: index % 2 === 0 ? "black" : "white",
      time: move.time,
    }));
  }

  return result;
}

// 格式化坐标显示
function formatPosition(x: number, y: number): string {
  const colLetters = "ABCDEFGHJKLMNOPQRST";
  return `${colLetters[x]}${y + 1}`;
}

// 格式化时间 - 显示用时（毫秒）
function formatTime(time: number): string {
  return `${time}ms`;
}

// 绘制棋盘
function drawBoard(): void {
  if (!boardCanvas.value) {
    console.error("boardCanvas 元素不存在");
    return;
  }

  const ctx = boardCanvas.value.getContext("2d");
  if (!ctx) {
    console.error("无法获取 2D 上下文");
    return;
  }

  const size = internalGameData.value.boardSize;
  const labelSize = 25;
  const cellSize = Math.min((canvasWidth.value - labelSize) / size, (canvasHeight.value - labelSize) / size);
  const offsetX = labelSize;
  const offsetY = labelSize;

  ctx.clearRect(0, 0, canvasWidth.value, canvasHeight.value);

  ctx.fillStyle = "#E8C095";
  ctx.fillRect(0, 0, canvasWidth.value, canvasHeight.value);

  ctx.font = "14px Arial";
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillStyle = "#000000";

  const colLetters = "ABCDEFGHJKLMNOPQRST";
  for (let i = 0; i < size; i++) {
    const x = offsetX + i * cellSize;
    const y = labelSize / 2;
    ctx.fillText(colLetters[i], x, y);
  }

  for (let i = 0; i < size; i++) {
    const x = labelSize / 2;
    const y = offsetY + i * cellSize;
    ctx.fillText((i + 1).toString(), x, y);
  }

  ctx.strokeStyle = "#000000";
  ctx.lineWidth = 1;

  for (let i = 0; i < size; i++) {
    ctx.beginPath();
    ctx.moveTo(offsetX, offsetY + i * cellSize);
    ctx.lineTo(offsetX + (size - 1) * cellSize, offsetY + i * cellSize);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(offsetX + i * cellSize, offsetY);
    ctx.lineTo(offsetX + i * cellSize, offsetY + (size - 1) * cellSize);
    ctx.stroke();
  }

  const starPoints = [
    { x: 3, y: 3 },
    { x: 3, y: size - 4 },
    { x: Math.floor((size - 1) / 2), y: Math.floor((size - 1) / 2) },
    { x: size - 4, y: 3 },
    { x: size - 4, y: size - 4 },
  ];

  ctx.fillStyle = "#000000";
  starPoints.forEach((point) => {
    ctx.beginPath();
    ctx.arc(offsetX + point.x * cellSize, offsetY + point.y * cellSize, cellSize / 8, 0, Math.PI * 2);
    ctx.fill();
  });

  drawStones();
}

// 绘制棋子
function drawStones(): void {
  if (!boardCanvas.value) return;

  const ctx = boardCanvas.value.getContext("2d");
  if (!ctx) return;

  const size = internalGameData.value.boardSize;
  const labelSize = 25;
  const cellSize = Math.min((canvasWidth.value - labelSize) / size, (canvasHeight.value - labelSize) / size);
  const offsetX = labelSize;
  const offsetY = labelSize;
  const stoneRadius = cellSize * 0.45;

  for (let i = 0; i < currentStep.value && i < internalGameData.value.moves.length; i++) {
    const move = internalGameData.value.moves[i];
    const x = offsetX + move.x * cellSize;
    const y = offsetY + move.y * cellSize;

    let currentRadius = stoneRadius;
    let currentAlpha = 1;

    if (i === currentStep.value - 1 && isDropAnimating.value) {
      const easeOut = 1 - Math.pow(1 - dropAnimationProgress.value, 3);
      currentRadius = stoneRadius * easeOut;
      currentAlpha = easeOut;

      const rippleRadius = stoneRadius * (1.5 + easeOut * 0.5);
      ctx.beginPath();
      ctx.arc(x, y, rippleRadius, 0, Math.PI * 2);
      ctx.strokeStyle = `rgba(255, 215, 0, ${0.5 * (1 - easeOut)})`;
      ctx.lineWidth = 2;
      ctx.stroke();
    }

    ctx.beginPath();
    ctx.arc(x, y, currentRadius, 0, Math.PI * 2);

    if (move.color === "black") {
      const gradient = ctx.createRadialGradient(x - currentRadius * 0.3, y - currentRadius * 0.3, 0, x, y, currentRadius);
      gradient.addColorStop(0, "#666666");
      gradient.addColorStop(1, "#000000");
      ctx.fillStyle = gradient;
    } else {
      const gradient = ctx.createRadialGradient(x - currentRadius * 0.3, y - currentRadius * 0.3, 0, x, y, currentRadius);
      gradient.addColorStop(0, "#FFFFFF");
      gradient.addColorStop(1, "#CCCCCC");
      ctx.fillStyle = gradient;
    }

    ctx.globalAlpha = currentAlpha;
    ctx.fill();
    ctx.strokeStyle = "#000000";
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.globalAlpha = 1;

    if (i === currentStep.value - 1) {
      const alpha = 0.7 + 0.3 * blinkIntensity.value;
      const borderColor = `rgba(255, 0, 0, ${alpha})`;
      const shadowBlur = 5 + 10 * blinkIntensity.value;

      ctx.beginPath();
      ctx.arc(x, y, currentRadius * 1.2, 0, Math.PI * 2);
      ctx.strokeStyle = borderColor;
      ctx.lineWidth = 3;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(x, y, currentRadius / 4, 0, Math.PI * 2);
      ctx.fillStyle = move.color === "black" ? "#FFFFFF" : "#000000";
      ctx.fill();

      ctx.shadowColor = `rgba(255, 215, 0, ${alpha})`;
      ctx.shadowBlur = shadowBlur;
    } else {
      ctx.shadowColor = "transparent";
      ctx.shadowBlur = 0;
    }
  }

  const { winner, winningLine } = evaluateBoard(size, internalGameData.value.moves, currentStep.value);

  if (winner && winningLine) {
    ctx.strokeStyle = "#FF0000";
    ctx.lineWidth = 3;
    ctx.lineCap = "round";
    ctx.lineJoin = "round";

    for (const line of winningLine) {
      const startX = offsetX + line.x1 * cellSize;
      const startY = offsetY + line.y1 * cellSize;
      const endX = offsetX + line.x2 * cellSize;
      const endY = offsetY + line.y2 * cellSize;

      if (isLineAnimating.value) {
        const easeOut = 1 - Math.pow(1 - lineAnimationProgress.value, 2);

        const currentEndX = startX + (endX - startX) * easeOut;
        const currentEndY = startY + (endY - startY) * easeOut;

        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(currentEndX, currentEndY);
        ctx.stroke();

        ctx.shadowColor = "#FF0000";
        ctx.shadowBlur = 10 * easeOut;
        ctx.beginPath();
        ctx.arc(currentEndX, currentEndY, 6, 0, Math.PI * 2);
        ctx.fillStyle = "#FF0000";
        ctx.fill();
        ctx.shadowBlur = 0;
      } else {
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.stroke();
      }
    }

    ctx.shadowColor = "transparent";
    ctx.shadowBlur = 0;
  }
}

// 控制函数
function gotoStep(step: number): void {
  const prevStep = currentStep.value;
  currentStep.value = Math.max(0, Math.min(step, internalGameData.value.moves.length));

  updateGameStatus();

  if (currentStep.value > prevStep && currentStep.value <= internalGameData.value.moves.length) {
    const { winner } = evaluateBoard(internalGameData.value.boardSize, internalGameData.value.moves, currentStep.value);
    if (winner && !internalGameData.value.winner) {
      startLineAnimation();
    } else {
      startDropAnimation();
    }
  } else {
    drawBoard();
  }
}

// 启动落子动画
function startDropAnimation() {
  isDropAnimating.value = true;
  dropAnimationProgress.value = 0;
  animationStartTime = Date.now();

  function animateDrop() {
    const elapsed = Date.now() - animationStartTime;
    dropAnimationProgress.value = Math.min(elapsed / DROP_ANIMATION_DURATION, 1);

    drawBoard();

    if (dropAnimationProgress.value < 1) {
      requestAnimationFrame(animateDrop);
    } else {
      isDropAnimating.value = false;
    }
  }

  animateDrop();
}

// 启动胜利连线动画
function startLineAnimation() {
  isLineAnimating.value = true;
  lineAnimationProgress.value = 0;
  animationStartTime = Date.now();

  function animateLine() {
    const elapsed = Date.now() - animationStartTime;
    lineAnimationProgress.value = Math.min(elapsed / LINE_ANIMATION_DURATION, 1);

    drawBoard();

    if (lineAnimationProgress.value < 1) {
      requestAnimationFrame(animateLine);
    } else {
      isLineAnimating.value = false;
    }
  }

  animateLine();
}

function gotoStart(): void {
  gotoStep(0);
}

function gotoEnd(): void {
  gotoStep(internalGameData.value.moves.length);
}

function prevStep(): void {
  gotoStep(currentStep.value - 1);
}

function nextStep(): void {
  gotoStep(currentStep.value + 1);
}

function togglePlay(): void {
  isPlaying.value = !isPlaying.value;
  if (isPlaying.value) {
    lastPlayTime = Date.now();
    playAnimation();
  } else if (animationFrameId) {
    cancelAnimationFrame(animationFrameId);
    animationFrameId = null;
  }
}

function playAnimation(): void {
  if (!isPlaying.value) return;

  const now = Date.now();
  const timeDiff = now - lastPlayTime;
  const stepInterval = 1000 / playSpeed.value;

  if (timeDiff >= stepInterval && !isDropAnimating.value && !isLineAnimating.value) {
    if (currentStep.value < internalGameData.value.moves.length) {
      nextStep();
      lastPlayTime = now;
    } else {
      isPlaying.value = false;
      return;
    }
  }

  animationFrameId = requestAnimationFrame(playAnimation);
}

// 检查指定位置是否有五连子
function checkWinning(
  board: Map<string, "black" | "white">,
  x: number,
  y: number,
  color: "black" | "white",
  size: number
): { x1: number; y1: number; x2: number; y2: number }[] | null {
  const directions = [
    { dx: 1, dy: 0 },
    { dx: 0, dy: 1 },
    { dx: 1, dy: 1 },
    { dx: 1, dy: -1 },
  ];

  for (const dir of directions) {
    let count = 1;
    let startX = x;
    let startY = y;
    let endX = x;
    let endY = y;

    for (let i = 1; i < 5; i++) {
      const nx = x + dir.dx * i;
      const ny = y + dir.dy * i;
      if (nx >= 0 && nx < size && ny >= 0 && ny < size && board.get(`${nx},${ny}`) === color) {
        count++;
        endX = nx;
        endY = ny;
      } else {
        break;
      }
    }

    for (let i = 1; i < 5; i++) {
      const nx = x - dir.dx * i;
      const ny = y - dir.dy * i;
      if (nx >= 0 && nx < size && ny >= 0 && ny < size && board.get(`${nx},${ny}`) === color) {
        count++;
        startX = nx;
        startY = ny;
      } else {
        break;
      }
    }

    if (count >= 5) {
      return [{ x1: startX, y1: startY, x2: endX, y2: endY }];
    }
  }

  return null;
}

// 根据当前局面判断胜负
function evaluateBoard(
  boardSize: number,
  moves: Move[],
  currentStep: number
): { winner: "black" | "white" | null; winningLine: { x1: number; y1: number; x2: number; y2: number }[] | null } {
  const board = new Map<string, "black" | "white">();

  for (let i = 0; i < currentStep && i < moves.length; i++) {
    const move = moves[i];
    board.set(`${move.x},${move.y}`, move.color);
  }

  for (let i = 0; i < currentStep && i < moves.length; i++) {
    const move = moves[i];
    const winningLine = checkWinning(board, move.x, move.y, move.color, boardSize);
    if (winningLine) {
      return { winner: move.color, winningLine };
    }
  }

  if (currentStep >= boardSize * boardSize) {
    return { winner: null, winningLine: null };
  }

  return { winner: null, winningLine: null };
}

// 监听步骤变化，重置闪烁效果
watch(currentStep, () => {
  blinkIntensity.value = 1;
  lastBlinkTime = Date.now();
});

// 监听父组件传递的游戏数据变化
watch(
  () => props.gameData,
  (newData) => {
    if (!newData.paramData || !newData.paramData.moves || !Array.isArray(newData.paramData.moves)) {
      return;
    }

    const currentMoves = newData.paramData.moves;
    const movesHash = JSON.stringify(currentMoves);

    if (movesHash === lastMovesHash) {
      return;
    }

    lastMovesHash = movesHash;

    console.log("Gomoku: 收到新的gameData:", newData);
    console.log("Gomoku: 处理paramData:", newData.paramData);
    console.log("Gomoku: 处理moves数据:", newData.paramData.moves);

    // 转换通用数据为五子棋数据
    internalGameData.value = convertGenericToGomokuData(newData);

    currentStep.value = internalGameData.value.moves.length;
    console.log("Gomoku: 设置步骤为moves长度并绘制所有棋子:", internalGameData.value.moves.length);
    console.log("Gomoku: internalGameData.moves:", internalGameData.value.moves);

    updateGameStatus();
    drawBoard();
  },
  { deep: true }
);

// 从evaluateBoard函数中分离游戏状态更新逻辑
function updateGameStatus() {
  const size = internalGameData.value.boardSize;
  const { winner, winningLine } = evaluateBoard(size, internalGameData.value.moves, currentStep.value);

  let needsUpdate = false;
  const updatedGameData = { ...internalGameData.value };

  if (winner) {
    if (updatedGameData.winner !== winner) {
      updatedGameData.winner = winner;
      updatedGameData.result = winner === "black" ? "黑方胜利" : "白方胜利";
      updatedGameData.winningLine = winningLine;
      needsUpdate = true;
    }
  } else if (currentStep.value >= size * size) {
    if (updatedGameData.result !== "平局") {
      updatedGameData.result = "平局";
      updatedGameData.winner = "draw";
      needsUpdate = true;
    }
  } else {
    if (updatedGameData.result !== "游戏进行中") {
      updatedGameData.result = "游戏进行中";
      updatedGameData.winner = undefined;
      updatedGameData.winningLine = undefined;
      needsUpdate = true;
    }
  }

  if (needsUpdate) {
    internalGameData.value = updatedGameData;
  }
}

// 响应式调整画布大小
function handleResize() {
  if (!boardCanvas.value) return;

  const container = boardCanvas.value.parentElement;
  if (container) {
    const containerWidth = container.clientWidth;
    const containerHeight = container.clientHeight;
    const size = Math.min(containerWidth, containerHeight);

    if (canvasWidth.value !== size || canvasHeight.value !== size) {
      canvasWidth.value = size;
      canvasHeight.value = size;
      drawBoard();
    }
  }
}

// 断点切换时主动重绘棋盘
watch(isMobile, () => {
  handleResize();
  drawBoard();
});

// 组件挂载时初始化
onMounted(() => {
  lastBlinkTime = Date.now();

  updateGameStatus();

  // 处理初始数据
  if (props.gameData.paramData) {
    if (props.gameData.paramData.moves && Array.isArray(props.gameData.paramData.moves)) {
      internalGameData.value = convertGenericToGomokuData(props.gameData);

      lastMovesHash = JSON.stringify(props.gameData.paramData.moves);

      currentStep.value = internalGameData.value.moves.length;
      drawBoard();
    }
  } else {
    console.log("Gomoku: 初始无数据，等待watch触发后绘制棋盘");
  }

  // 启动闪烁动画
  function animateBlink() {
    if (!boardCanvas.value) {
      return;
    }

    const now = Date.now();
    const timeDiff = now - lastBlinkTime;
    const blinkPeriod = 1000;

    blinkIntensity.value = 0.5 + 0.5 * Math.sin((timeDiff * Math.PI * 2) / blinkPeriod);

    if (currentStep.value >= 0 && !isPlaying.value) {
      drawBoard();
    }

    animationFrameId = requestAnimationFrame(animateBlink);
  }

  animateBlink();

  // 响应式调整画布大小
  handleResize();
  window.addEventListener("resize", handleResize);

  onUnmounted(() => {
    window.removeEventListener("resize", handleResize);
    if (animationFrameId) {
      cancelAnimationFrame(animationFrameId);
      animationFrameId = null;
    }
  });
});
</script>

